<template>
  <div>
    <EventWorkspaceHeader :event-id="props.eventId" />

    <!-- Content toolbar -->
    <div class="mb-5 mt-8 flex flex-wrap items-center justify-between gap-3">
      <div>
        <h2 class="font-display text-xl text-gray-900">Invitations</h2>
        <p class="mt-0.5 text-sm text-gray-500">{{ totalInvitations }} invitations · {{ sentCount }} sent</p>
      </div>
      <div class="flex gap-2">
        <Button @click="generateBulkInvitations" variant="ghost" size="sm" :loading="generating" iconLeft="zap" :label="__('Generate')" class="hidden sm:inline-flex" />
        <Button @click="generateBulkInvitations" variant="ghost" size="sm" :loading="generating" iconLeft="zap" class="sm:hidden" />
        <Button @click="sendBulk" variant="solid" size="sm" iconLeft="send" :label="__('Send All')" />
      </div>
    </div>

    <!-- Bulk Send Modal -->
    <Dialog :options="{ title: 'Send Invitations' }" v-model="showSendModal">
      <template #body-content>
        <div class="space-y-4">
          <p class="text-sm text-gray-600">
            Send pending invitations for this event. Select the delivery method:
          </p>
          <div class="grid grid-cols-3 gap-3">
            <button
              v-for="medium in deliveryMediums"
              :key="medium.value"
              @click="selectedMedium = medium.value"
              class="flex flex-col items-center gap-2 p-4 rounded-lg border-2 transition-colors"
              :class="selectedMedium === medium.value ? 'border-blue-500 bg-blue-50' : 'border-gray-200 hover:border-gray-300'"
            >
              <FeatherIcon :name="medium.icon" class="h-8 w-8" :class="selectedMedium === medium.value ? 'text-blue-600' : 'text-gray-400'" />
              <span class="text-sm font-medium" :class="selectedMedium === medium.value ? 'text-blue-700' : 'text-gray-600'">{{ medium.label }}</span>
            </button>
          </div>
          <div class="bg-gray-50 rounded-lg p-3 text-sm text-gray-500">
            <p><strong>{{ pendingInvitations.length }}</strong> pending · <strong>{{ stats.failed }}</strong> failed (will retry)</p>
          </div>
        </div>
      </template>
      <template #actions>
        <Button @click="showSendModal = false; sendResult = null" variant="ghost" size="sm">Cancel</Button>
        <Button @click="sendWithMedium" variant="solid" size="sm" :loading="sending" :disabled="!selectedMedium">
          Send via {{ selectedMedium || '...' }}
        </Button>
      </template>
    </Dialog>

    <!-- Card Generation Progress Modal -->
    <Dialog :options="{ title: 'Generating Invitation Cards', size: 'lg' }" v-model="showProgressModal" :dismissible="progressFinished">
      <template #body-content>
        <div class="space-y-4">
          <!-- Live progress while generating -->
          <div v-if="!progressFinished">
            <div class="flex items-center justify-between mb-2">
              <p class="text-sm text-gray-600">Generating personalized cards…</p>
              <p class="text-sm font-medium text-gray-900">{{ progressState.done }} / {{ progressState.total || '…' }}</p>
            </div>
            <div class="h-2 bg-gray-100 rounded-full overflow-hidden">
              <div class="h-full bg-blue-600 transition-all duration-300" :style="{ width: progressPercent + '%' }"></div>
            </div>
            <p class="text-xs text-gray-500 mt-2">
              <span v-if="progressState.current">Now: {{ progressState.current }}</span>
              <span v-else>Starting…</span>
            </p>
          </div>

          <!-- Summary when done -->
          <div v-else class="rounded-lg p-4" :class="progressState.failed ? 'bg-amber-50 border border-amber-200' : 'bg-green-50 border border-green-200'">
            <p class="text-sm font-medium" :class="progressState.failed ? 'text-amber-800' : 'text-green-800'">
              {{ progressState.done - progressState.failed }} card(s) generated
              <span v-if="progressState.failed">, {{ progressState.failed }} failed</span>
            </p>
            <p class="text-xs mt-1" :class="progressState.failed ? 'text-amber-600' : 'text-green-600'">
              Each card now shows the event photo and the guest's own QR code in the template layout.
            </p>
          </div>

          <!-- Live per-guest list -->
          <div v-if="progressState.items.length" class="border rounded-lg divide-y max-h-64 overflow-y-auto">
            <div v-for="(item, i) in progressState.items" :key="i" class="flex items-center justify-between px-3 py-2 text-sm">
              <span class="text-gray-800">
                {{ item.guest_name }}
                <span class="text-xs text-gray-400 font-mono">{{ item.invite_code }}</span>
              </span>
              <span v-if="item.status === 'error'" class="text-xs text-red-600" :title="item.error">Failed</span>
              <span v-else class="inline-flex items-center gap-1 text-xs text-green-600">
                <FeatherIcon name="check" class="h-3 w-3" />
                Card ready
              </span>
            </div>
          </div>
        </div>
      </template>
      <template #actions>
        <Button v-if="progressFinished" @click="closeProgressModal" variant="solid" size="sm">Close</Button>
      </template>
    </Dialog>

    <!-- Send Results Modal -->
    <Dialog :options="{ title: 'Send Results' }" v-model="showSendResultModal">
      <template #body-content>
        <div class="py-2 space-y-3">
          <div class="flex items-center gap-3 p-3 rounded-lg" :class="sendResult?.error ? 'bg-red-50 border border-red-200' : 'bg-green-50 border border-green-200'">
            <FeatherIcon :name="sendResult?.error ? 'alert-triangle' : 'check-circle'" 
              :class="sendResult?.error ? 'text-red-500' : 'text-green-500'" class="h-8 w-8 flex-shrink-0" />
            <div>
              <p class="text-sm font-medium" :class="sendResult?.error ? 'text-red-800' : 'text-green-800'">
                {{ sendResult?.error ? 'Send Failed' : 'Sent Successfully' }}
              </p>
              <p class="text-xs" :class="sendResult?.error ? 'text-red-600' : 'text-green-600'">
                {{ sendResult?.message }}
              </p>
            </div>
          </div>
          <div v-if="sendResult?.sent?.length" class="bg-blue-50 rounded-lg p-3 text-sm">
            <p class="font-medium text-blue-800 mb-1">Sent ({{ sendResult.sent.length }})</p>
            <p class="text-xs text-blue-600 space-y-0.5 max-h-24 overflow-y-auto">
              <span v-for="s in sendResult.sent" :key="s" class="block">{{ s }}</span>
            </p>
          </div>
          <div v-if="sendResult?.failed?.length" class="bg-red-50 rounded-lg p-3 text-sm">
            <p class="font-medium text-red-800 mb-1">Failed ({{ sendResult.failed.length }})</p>
            <p class="text-xs text-red-600 space-y-0.5 max-h-24 overflow-y-auto">
              <span v-for="f in sendResult.failed" :key="f" class="block">{{ f }}</span>
            </p>
          </div>
        </div>
      </template>
      <template #actions>
        <Button @click="showSendResultModal = false; sendResult = null" variant="solid" size="sm">Close</Button>
      </template>
    </Dialog>

    <!-- Single Send Modal -->
    <Dialog :options="{ title: sendingInvitation?.status === 'Failed' ? 'Retry Invitation' : 'Send Invitation' }" v-model="showSingleSendModal">
      <template #body-content>
        <div class="space-y-4">
          <div v-if="sendingInvitation" class="rounded-lg p-3 text-sm" :class="sendingInvitation?.status === 'Failed' ? 'bg-orange-50 border border-orange-200' : 'bg-gray-50'">
            <p class="text-gray-700">Sending to: <strong>{{ sendingInvitation?.guest_name }}</strong></p>
            <p class="text-xs text-gray-400 mt-1">Invite code: {{ sendingInvitation?.invite_code }}</p>
            <p v-if="sendingInvitation?.status === 'Failed' && sendingInvitation?.delivery_error" class="text-xs text-orange-600 mt-1">Previous error: {{ sendingInvitation.delivery_error }}</p>
          </div>
          <p class="text-sm text-gray-600">Select the delivery method:</p>
          <div class="grid grid-cols-3 gap-3">
            <button
              v-for="medium in deliveryMediums"
              :key="medium.value"
              @click="singleSendMedium = medium.value"
              class="flex flex-col items-center gap-2 p-4 rounded-lg border-2 transition-colors"
              :class="singleSendMedium === medium.value ? 'border-blue-500 bg-blue-50' : 'border-gray-200 hover:border-gray-300'"
            >
              <FeatherIcon :name="medium.icon" class="h-8 w-8" :class="singleSendMedium === medium.value ? 'text-blue-600' : 'text-gray-400'" />
              <span class="text-sm font-medium" :class="singleSendMedium === medium.value ? 'text-blue-700' : 'text-gray-600'">{{ medium.label }}</span>
            </button>
          </div>
        </div>
      </template>
      <template #actions>
        <Button @click="showSingleSendModal = false; sendingInvitation = null" variant="ghost" size="sm">Cancel</Button>
        <Button @click="confirmSingleSend" variant="solid" size="sm" :loading="sending">
          {{ sendingInvitation?.status === 'Failed' ? 'Retry' : 'Send' }} via {{ singleSendMedium || '...' }}
        </Button>
      </template>
    </Dialog>

    <!-- Statistics -->
    <div class="grid grid-cols-2 sm:grid-cols-4 gap-3 sm:gap-4 mb-6">
      <div class="bg-white rounded-lg border p-4 text-center">
        <p class="text-lg font-semibold text-gray-900">{{ stats.total || 0 }}</p>
        <p class="text-xs text-gray-500">Total</p>
      </div>
      <div class="bg-white rounded-lg border p-4 text-center">
        <p class="text-lg font-semibold text-blue-600">{{ stats.sent || 0 }}</p>
        <p class="text-xs text-gray-500">Sent</p>
      </div>
      <div class="bg-white rounded-lg border p-4 text-center">
        <p class="text-lg font-semibold text-green-600">{{ stats.delivered || 0 }}</p>
        <p class="text-xs text-gray-500">Delivered</p>
      </div>
      <div class="bg-white rounded-lg border p-4 text-center">
        <p class="text-lg font-semibold text-red-600">{{ stats.failed || 0 }}</p>
        <p class="text-xs text-gray-500">Failed</p>
      </div>
    </div>

    <!-- Invitations List -->
    <div class="bg-white rounded-lg border overflow-hidden">
      <div class="overflow-x-auto">
        <table class="w-full min-w-[700px]">
          <thead class="bg-gray-50 border-b">
            <tr>
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Guest</th>
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase hidden sm:table-cell">Code</th>
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase hidden lg:table-cell">Delivery</th>
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase hidden md:table-cell">RSVP</th>					<th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase hidden md:table-cell">Guests</th>
              <th class="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Actions</th>
            </tr>
          </thead>
          <tbody class="divide-y">
            <tr v-for="inv in invitations" :key="inv.name" class="hover:bg-gray-50" :class="inv.status === 'Failed' ? 'bg-red-50/30' : ''">
              <td class="px-4 py-3">
                <p class="text-sm text-gray-900">{{ inv.guest_name }}</p>
                <p class="text-xs text-gray-400 sm:hidden font-mono">{{ inv.invite_code }}</p>
              </td>
              <td class="px-4 py-3 text-sm font-mono text-gray-600 hidden sm:table-cell">{{ inv.invite_code }}</td>
              <td class="px-4 py-3">
                <span :class="statusBadge(inv.status)" class="text-xs px-2 py-1 rounded-full">{{ inv.status }}</span>
              </td>
              <td class="px-4 py-3 hidden lg:table-cell">
                <div class="text-sm">
                  <span :class="deliveryBadge(inv.delivery_status)">{{ inv.delivery_status || 'Pending' }}</span>
                  <p v-if="inv.sent_at" class="text-xs text-gray-400 mt-0.5">{{ formatDateTime(inv.sent_at) }}</p>
                  <p v-if="inv.delivered_at" class="text-xs text-green-500 mt-0.5">Delivered: {{ formatDateTime(inv.delivered_at) }}</p>
                  <p v-if="inv.delivery_status === 'Failed' && inv.delivery_error" class="text-xs text-red-500 mt-1 max-w-[200px] truncate" :title="inv.delivery_error">{{ inv.delivery_error }}</p>
                </div>
              </td>
              <td class="px-4 py-3 hidden md:table-cell">
                <span :class="rsvpBadge(inv.rsvp_status)" class="text-xs px-2 py-1 rounded-full">
                  {{ inv.rsvp_status || 'Pending' }}
                </span>
              </td>					<td class="px-4 py-3 text-sm text-gray-600 hidden md:table-cell">
						{{ inv.number_of_attendees || 1 }}
					</td>
              <td class="px-4 py-3 text-right">
                <div class="flex justify-end gap-1 items-center">
                  <Button v-if="inv.qr_code_image" @click="downloadQR(inv)" variant="ghost" class="text-xs hidden sm:inline-flex">QR</Button>
                  <Button @click="downloadCard(inv)" variant="ghost" class="text-xs" :loading="inv._downloading">Card</Button>
                  <!-- Send: only for Draft/Ready -->
                  <Button
                    v-if="inv.status === 'Draft' || inv.status === 'Ready'"
                    @click="openSingleSend(inv)"
                    theme="gray"
                    variant="subtle"
                    size="sm"
                    iconLeft="send"
                    label="Send"
                  />
                  <!-- Retry: only for Failed -->
                  <Button
                    v-if="inv.status === 'Failed'"
                    @click="openSingleSend(inv)"
                    theme="orange"
                    variant="subtle"
                    size="sm"
                    iconLeft="refresh-cw"
                    label="Retry"
                  />
                  <!-- Sent badge: for sent/delivered -->
                  <span v-if="inv.status === 'Sent' || inv.status === 'Delivered'" class="inline-flex items-center gap-1 text-xs text-green-600 bg-green-50 px-2 py-1 rounded-full">
                    <FeatherIcon name="check" class="h-3 w-3" />
                    Sent
                  </span>
                </div>
              </td>
            </tr>
            <tr v-if="!invitations.length">
              <td colspan="8" class="px-4 py-12 text-center text-gray-500 text-sm">
                No invitations yet. Generate invitations from the Guests page.
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, onUnmounted, getCurrentInstance } from 'vue'
import { frappeRequest } from '@/utils/api'
import EventWorkspaceHeader from '@/components/EventWorkspaceHeader.vue'
import { useNotifications } from '@/composables/notifications'
import { FeatherIcon } from 'frappe-ui'

const props = defineProps({ eventId: String })

const invitations = ref([])
const totalInvitations = ref(0)
const generating = ref(false)
const sending = ref(false)
const showSendModal = ref(false)
const showSendResultModal = ref(false)
const showSingleSendModal = ref(false)
const selectedMedium = ref('WhatsApp')
const singleSendMedium = ref('WhatsApp')
const sendingInvitation = ref(null)
const sendResult = ref(null)

// Card generation progress (realtime via socket)
const showProgressModal = ref(false)
const progressState = ref({ done: 0, total: 0, failed: 0, current: '', items: [] })

const progressFinished = computed(() => progressState.value.finished)
const progressPercent = computed(() => {
  const { done, total } = progressState.value
  if (!total) return 0
  return Math.min(100, Math.round((done / total) * 100))
})

const { showError } = useNotifications()

let progressSocket = null

function getSocket() {
  if (progressSocket) return progressSocket
  const instance = getCurrentInstance()
  progressSocket = instance?.appContext?.config?.globalProperties?.$socket || null
  return progressSocket
}

function onCardProgress(data) {
  if (!data) return
  progressState.value.done = data.index || 0
  progressState.value.total = data.total || progressState.value.total
  progressState.value.current = data.guest_name || ''
  progressState.value.failed = progressState.value.failed + (data.status === 'error' ? 1 : 0)
  progressState.value.items.push({
    guest_name: data.guest_name,
    invite_code: data.invite_code,
    status: data.status,
    error: data.error,
  })
  if (data.index && data.total && data.index >= data.total) {
    progressState.value.finished = true
  }
}

function closeProgressModal() {
  showProgressModal.value = false
  const socket = getSocket()
  if (socket) socket.off('invite_card_progress', onCardProgress)
  progressState.value = { done: 0, total: 0, failed: 0, current: '', finished: false, items: [] }
}

onUnmounted(() => {
  const socket = getSocket()
  if (socket) socket.off('invite_card_progress', onCardProgress)
})

const deliveryMediums = [
  { label: 'WhatsApp', value: 'WhatsApp', icon: 'message-circle' },
  { label: 'SMS', value: 'SMS', icon: 'message-square' },
  { label: 'Email', value: 'Email', icon: 'mail' },
]

const stats = computed(() => {
  const list = invitations.value
  return {
    total: list.length,
    sent: list.filter(i => i.status === 'Sent').length,
    delivered: list.filter(i => i.delivery_status === 'Delivered').length,
    failed: list.filter(i => i.delivery_status === 'Failed' || i.status === 'Failed').length,
  }
})

const sentCount = computed(() => stats.value.sent)

const pendingInvitations = computed(() => {
  return invitations.value.filter(i => i.status === 'Ready' || i.status === 'Draft')
})

onMounted(async () => {
  await loadInvitations()
})

async function loadInvitations() {
  try {
    const data = await frappeRequest({
      url: 'invite.api.invitation.get_list',
      params: { event: props.eventId },
    })
    invitations.value = data.invitations || []
    totalInvitations.value = data.total || 0
  } catch (e) {
    console.error('Failed to load invitations:', e)
  }
}

async function generateBulkInvitations() {
  generating.value = true
  try {
    // 1) Ensure an invitation exists for every guest
    const { guests } = await frappeRequest({
      url: 'invite.api.guest.get_list',
      params: { event: props.eventId },
    })
    const guestIds = (guests || []).map(g => g.name)
    if (!guestIds.length) {
      sendResult.value = { error: true, message: 'No guests found to invite.', sent: [], failed: [] }
      showSendResultModal.value = true
      return
    }
    await frappeRequest({
      url: 'invite.api.invitation.create_invitations',
      params: { 
        event: props.eventId,
        guest_ids: JSON.stringify(guestIds),
        invitation_type: 'Digital',
        delivery_method: selectedMedium.value,
      },
    })

    // 2) Generate the personalized cards with realtime progress
    progressState.value = { done: 0, total: 0, failed: 0, current: '', finished: false, items: [] }
    showProgressModal.value = true
    const socket = getSocket()
    if (socket) {
      socket.off('invite_card_progress', onCardProgress)
      socket.on('invite_card_progress', onCardProgress)
    }

    try {
      const result = await frappeRequest({
        url: 'invite.api.invitation.generate_cards',
        params: { event: props.eventId },
      })
      progressState.value.total = result.total || progressState.value.total
      progressState.value.finished = true
    } catch (genError) {
      // If nothing was generated at all (e.g. no event image), close the
      // progress modal and surface the error normally.
      progressState.value.finished = true
      if (!progressState.value.items.length) {
        showProgressModal.value = false
        throw genError
      }
    }
    await loadInvitations()
  } catch (e) {
    console.error('Failed to generate invitations:', e)
    showProgressModal.value = false
    // e.message is only "<url> <exc_type>" (e.g. "/api/method/... ValidationError");
    // the real reason (e.g. "Please upload an Event Image...") is in e.messages.
    sendResult.value = { error: true, message: e.messages?.[0] || e.message || 'Failed to generate invitations', sent: [], failed: [] }
    showSendResultModal.value = true
  } finally {
    generating.value = false
  }
}

async function sendWithMedium() {
  sending.value = true
  try {
    const result = await frappeRequest({
      url: 'invite.api.invitation.send',
      params: { 
        event: props.eventId, 
        delivery_method: selectedMedium.value,
      },
    })
    showSendModal.value = false
    sendResult.value = {
      error: false,
      message: `Sent ${result.sent?.length || 0} invitations, ${result.failed?.length || 0} failed.`,
      sent: result.sent || [],
      failed: result.failed || [],
    }
    showSendResultModal.value = true
    await loadInvitations()
  } catch (e) {
    console.error('Failed to send invitations:', e)
    sendResult.value = { error: true, message: e.message || 'Failed to send', sent: [], failed: [] }
    showSendResultModal.value = true
  } finally {
    sending.value = false
  }
}

async function sendBulk() {
  selectedMedium.value = 'WhatsApp'
  showSendModal.value = true
}

async function openSingleSend(inv) {
  sendingInvitation.value = inv
  singleSendMedium.value = inv.delivery_method || 'WhatsApp'
  showSingleSendModal.value = true
}

async function confirmSingleSend() {
  sending.value = true
  try {
    const result = await frappeRequest({
      url: 'invite.invite.doctype.invitation.invitation.send_single_invitation',
      params: { 
        invitation: sendingInvitation.value?.name,
        delivery_method: singleSendMedium.value,
      },
    })
    showSingleSendModal.value = false
    sendResult.value = {
      error: !result.success,
      message: result.message || `Invitation sent via ${singleSendMedium.value}.`,
      sent: result.success ? [sendingInvitation.value?.guest_name || 'Invitation'] : [],
      failed: result.success ? [] : [sendingInvitation.value?.guest_name || 'Invitation'],
    }
    showSendResultModal.value = true
    sendingInvitation.value = null
    await loadInvitations()
  } catch (e) {
    console.error('Failed to send invitation:', e)
    sendResult.value = { error: true, message: e.messages?.[0] || e.message || 'Failed to send invitation', sent: [], failed: [] }
    showSendResultModal.value = true
  } finally {
    sending.value = false
  }
}

async function downloadCard(inv) {
  inv._downloading = true
  try {
    const result = await frappeRequest({
      url: 'invite.api.card.generate_invitation_card',
      params: { invitation: inv.name },
    })
    if (result.card_url) {
      window.open(result.card_url, '_blank')
    }
  } catch (e) {
    console.error('Failed to generate card:', e)
    showError(e.messages?.[0] || e.message || 'Failed to generate card. Make sure the event has an image uploaded.')
  } finally {
    inv._downloading = false
    await loadInvitations()
  }
}

function downloadQR(inv) {
  if (inv.qr_code_image) {
    window.open(inv.qr_code_image, '_blank')
  }
}

function formatDateTime(dt) {
  if (!dt) return ''
  return new Date(dt).toLocaleString()
}

function statusBadge(status) {
  const classes = {
    'Draft': 'bg-gray-50 text-gray-600',
    'Ready': 'bg-blue-50 text-blue-700',
    'Sent': 'bg-green-50 text-green-700',
    'Delivered': 'bg-green-50 text-green-700',
    'Failed': 'bg-red-50 text-red-700',
    'Cancelled': 'bg-gray-100 text-gray-500',
  }
  return classes[status] || 'bg-gray-50 text-gray-600'
}

function deliveryBadge(status) {
  const classes = {
    'Pending': 'bg-gray-50 text-gray-600',
    'Sent': 'bg-blue-50 text-blue-700',
    'Delivered': 'bg-green-50 text-green-700',
    'Failed': 'bg-red-50 text-red-700',
  }
  return classes[status] || 'bg-gray-50 text-gray-600'
}

function rsvpBadge(status) {
  const classes = {
    'Accepted': 'bg-green-50 text-green-700',
    'Declined': 'bg-red-50 text-red-700',
    'Pending': 'bg-gray-50 text-gray-600',
    'Maybe': 'bg-amber-50 text-amber-700',
  }
  return classes[status] || 'bg-gray-50 text-gray-600'
}
</script>
